<script setup lang="ts">
import { api } from "../api/client";
import { useEditorStore } from "../stores/editor";
const store = useEditorStore();
async function validate() { if (!store.projectId) return; const report = await store.run("Validation", () => api.validate(store.projectId)); if (store.graph) store.graph = { ...store.graph, validation: report } }
function focus(issue: { layer_id?: string | null; relation_id?: string | null }) { if (issue.layer_id) { store.select({ kind: "layer", id: issue.layer_id }); store.view = "editor" } else if (issue.relation_id) { store.select({ kind: "relation", id: issue.relation_id }); store.view = "editor" } }
</script>
<template><section class="page"><div class="page-title"><div><p class="eyebrow">DESIGN INTEGRITY</p><h1>Validation</h1><p>저장된 raw graph를 서버 규칙으로 검사합니다.</p></div><button class="primary" :disabled="!store.projectId" @click="validate">검증 실행</button></div><div v-if="store.graph" class="validation-layout"><div class="panel validation-summary" :class="store.graph.validation.ok ? 'ok' : 'error'"><span>{{ store.graph.validation.ok ? '✓' : '!' }}</span><div><strong>{{ store.graph.validation.ok ? 'Graph is valid' : 'Validation failed' }}</strong><p>오류 {{ store.graph.validation.issues.filter(row => row.severity === 'error').length }} · 경고 {{ store.graph.validation.issues.filter(row => row.severity === 'warning').length }}</p></div></div><div class="panel"><button v-for="(issue, index) in store.graph.validation.issues" :key="index" class="issue-row" :class="issue.severity" @click="focus(issue)"><b>{{ issue.severity }}</b><span><strong>{{ issue.code }}</strong><small>{{ issue.message }}</small></span><em>Canvas에서 보기 →</em></button><p v-if="!store.graph.validation.issues.length" class="empty">발견된 문제가 없습니다.</p></div></div><div v-else class="empty-page">프로젝트를 선택하세요.</div></section></template>
